import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import requests


class DatadogMetricsClient:
    def __init__(self, api_key: Optional[str] = None, app_key: Optional[str] = None, site: Optional[str] = None):
        self.api_key = api_key or os.getenv("DD_API_KEY")
        self.app_key = app_key or os.getenv("DD_APP_KEY")
        self.site = site or os.getenv("DD_SITE", "datadoghq.com")
        if not self.api_key or not self.app_key:
            raise ValueError("Datadog API credentials are required via DD_API_KEY and DD_APP_KEY.")
        self.base_url = f"https://api.{self.site}"

    def query_metric(self, metric_name: str, start: datetime, end: datetime, interval_seconds: int = 60) -> Dict[str, Any]:
        if start.tzinfo is None:
            start = start.replace(tzinfo=timezone.utc)
        if end.tzinfo is None:
            end = end.replace(tzinfo=timezone.utc)

        url = f"{self.base_url}/api/v1/query"
        params = {
            "from": int(start.timestamp()),
            "to": int(end.timestamp()),
            "query": metric_name,
        }
        headers = {
            "DD-API-KEY": self.api_key,
            "DD-APPLICATION-KEY": self.app_key,
            "Accept": "application/json",
        }
        response = requests.get(url, params=params, headers=headers, timeout=30)
        response.raise_for_status()
        payload = response.json()

        series_list: List[Dict[str, Any]] = payload.get("series", [])
        datapoints: List[Dict[str, Any]] = []
        for series in series_list:
            for point in series.get("pointlist", []):
                ts_ms, value = point
                if value is None:
                    continue
                datapoints.append(
                    {
                        "metric": series.get("expression") or metric_name,
                        "timestamp": datetime.fromtimestamp(ts_ms / 1000.0, tz=timezone.utc).isoformat(),
                        "value": value,
                        "scope": series.get("scope"),
                        "host": series.get("host"),
                    }
                )

        datapoints.sort(key=lambda x: x["timestamp"])
        return {
            "metric": metric_name,
            "start": start.isoformat(),
            "end": end.isoformat(),
            "interval_seconds": interval_seconds,
            "datapoints": datapoints,
            "raw": payload,
        }


def query_recent_datapoints(metric_name: str, minutes: int = 60, api_key: Optional[str] = None, app_key: Optional[str] = None) -> Dict[str, Any]:
    end = datetime.now(timezone.utc)
    start = end - timedelta(minutes=minutes)
    client = DatadogMetricsClient(api_key=api_key, app_key=app_key)
    return client.query_metric(metric_name=metric_name, start=start, end=end)
